"use client"; import { useParams, useRouter } from "next/navigation"; import { useQuery, useMutation, useQueryClient } from "@tanstack/react-query"; import { api } from "@/lib/api/services"; import { LoadingState, ErrorState } from "@/components/PageStates"; import { Button } from "@/components/ui/button"; import { Input } from "@/components/ui/input"; import { Textarea } from "@/components/ui/textarea"; import { Label } from "@/components/ui/label"; import { useState, useEffect } from "react";
export default function ProjectDetail(){const {id}=useParams<{id:string}>();const router=useRouter();const qc=useQueryClient();const q=useQuery({queryKey:["project",id],queryFn:()=>api.project(id)});const [title,setTitle]=useState("");const [desc,setDesc]=useState("");
 useEffect(()=>{if(q.data){setTitle(String(q.data.title||q.data.name||""));setDesc(String(q.data.description||""));}},[q.data]);
 const save=useMutation({mutationFn:()=>api.updateProject(id,{title,description:desc}),onSuccess:()=>qc.invalidateQueries({queryKey:["project",id]})});
 const del=useMutation({mutationFn:()=>api.deleteProject(id),onSuccess:()=>router.push("/app/projects")});
 if(q.isLoading) return <LoadingState/>; if(q.error||!q.data) return <ErrorState message="Project not found"/>;
 return <div className="max-w-2xl"><p className="text-xs text-zinc-500"><a href="/app/projects" className="hover:underline">Projects</a> / Editor</p><h1 className="mt-2 text-2xl font-semibold tracking-tight">Project editor</h1><form onSubmit={e=>{e.preventDefault();save.mutate();}} className="mt-6 space-y-4"><div className="space-y-2"><Label htmlFor="t">Title</Label><Input id="t" value={title} onChange={e=>setTitle(e.target.value)} required/></div><div className="space-y-2"><Label htmlFor="d">Description</Label><Textarea id="d" rows={6} value={desc} onChange={e=>setDesc(e.target.value)}/></div>{save.isSuccess&&<p className="text-sm text-emerald-300">Saved.</p>}<div className="flex gap-2"><Button type="submit" disabled={save.isPending}>{save.isPending?"Saving…":"Save changes"}</Button><Button type="button" variant="outline" onClick={()=>{if(confirm("Delete this project?"))del.mutate();}}>Delete</Button></div></form></div>;}
